import { useLoader } from '@react-three/fiber';
import {
  BufferAttribute,
  NearestFilter,
  SRGBColorSpace,
  TextureLoader,
  type BufferGeometry,
  type Group,
  type Mesh,
  type Texture,
} from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { MeshoptDecoder } from 'three/examples/jsm/libs/meshopt_decoder.module.js';

/**
 * The Paper & Ink 3D assets, all generated by `scripts/gen-crystals.mjs` (our own crystals, emblems and textures).
 * Served from `public/`, so they load from 'self' under the CSP.
 */
export const CRYSTALS_URL = '/models/crystals.glb';
export const EMBLEMS_URL = '/models/emblems.glb';
/** The foil shader computes its own surface; only the pixel sprite is a texture. */
const PIXEL_URL = '/textures/pixel-crystal.png';

export type RockName =
  | 'rock-a'
  | 'rock-b'
  | 'rock-c'
  | 'rock-d'
  | 'rock-e'
  | 'rock-f'
  | 'rock-core'
  | 'shard-a'
  | 'shard-b';

export const OBJECT_ROCKS: readonly RockName[] = [
  'rock-a',
  'rock-b',
  'rock-c',
  'rock-d',
  'rock-e',
  'rock-f',
];

export interface CrystalAssets {
  rock: (name: RockName) => BufferGeometry;
  /** A fresh copy of an emblem group (the shape held inside a crystal). */
  emblem: (id: string) => Group;
  pixel: Texture;
}

let prepared = false;

/** The models are EXT_meshopt_compression; three ships the (WASM-in-JS) decoder, so it loads from 'self'. */
const withMeshopt = (loader: GLTFLoader) => {
  loader.setMeshoptDecoder(MeshoptDecoder);
};

/**
 * The rocks ship with 16-bit positions whose dequantise scale sits on their node. The world (and `fracture.ts`) uses
 * bare geometry, so bake the node transform back into float attributes, once per rock.
 */
const baked = new WeakMap<Mesh, BufferGeometry>();
function bakedGeometry(mesh: Mesh): BufferGeometry {
  const hit = baked.get(mesh);
  if (hit) return hit;
  const g = mesh.geometry.clone();
  for (const name of Object.keys(g.attributes)) {
    const a = g.getAttribute(name);
    if (a.array instanceof Float32Array && !a.normalized) continue;
    const out = new Float32Array(a.count * a.itemSize);
    for (let i = 0; i < a.count; i++)
      for (let c = 0; c < a.itemSize; c++) out[i * a.itemSize + c] = a.getComponent(i, c);
    g.setAttribute(name, new BufferAttribute(out, a.itemSize));
  }
  mesh.updateMatrix();
  g.applyMatrix4(mesh.matrix);
  g.computeBoundingBox();
  g.computeBoundingSphere();
  baked.set(mesh, g);
  return g;
}

/** Suspends until the files are in. Textures are set up once: they are cached and shared. */
export function useCrystalAssets(): CrystalAssets {
  const crystals = useLoader(GLTFLoader, CRYSTALS_URL, withMeshopt);
  const emblems = useLoader(GLTFLoader, EMBLEMS_URL, withMeshopt);
  const pixel = useLoader(TextureLoader, PIXEL_URL);
  if (!prepared) {
    prepared = true;
    pixel.magFilter = NearestFilter;
    pixel.minFilter = NearestFilter;
    pixel.generateMipmaps = false;
    pixel.colorSpace = SRGBColorSpace;
  }
  return {
    rock: (name) => {
      const mesh = crystals.scene.getObjectByName(name) as Mesh | undefined;
      if (!mesh) throw new Error(`crystal ${name} missing from ${CRYSTALS_URL}`);
      return bakedGeometry(mesh);
    },
    emblem: (id) => {
      const group = emblems.scene.getObjectByName(id) as Group | undefined;
      if (!group) throw new Error(`emblem ${id} missing from ${EMBLEMS_URL}`);
      return group.clone();
    },
    pixel,
  };
}

/** Start the downloads before the world mounts. */
export function preloadCrystalAssets(): void {
  useLoader.preload(GLTFLoader, CRYSTALS_URL, withMeshopt);
  useLoader.preload(GLTFLoader, EMBLEMS_URL, withMeshopt);
  useLoader.preload(TextureLoader, PIXEL_URL);
}
